type HumanComparisonProps = z.infer<typeof HumanComparisonSchema>;

// ----------------------------------------------------
// Main Component
// ----------------------------------------------------

const HumanComparison: React.FC<HumanComparisonProps> = ({
  backgroundColor = "#F7F1DE",
  transparentBackground = false,
  durationInSeconds = 14,
  textColor = "#262626",
  rightGroupColor = "#3D6E45",
  leftGroupColor = "#A04040",
  rightGroupLabel = "Rosemary Oil",
  leftGroupLabel = "Minoxidil 2%",
  timeLabel = "6 MONTHS",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // ----------------------------------------------------
  // SCENE 1 TIMINGS (0 - 135 frames)
  // ----------------------------------------------------
  
  // Phase 1: 0 - 30 frames: Figures Staggered Fade In
  
  // Phase 2: 30 - 55 frames: Smooth Separation & Divider Line Appearance
  const splitProgress = interpolate(frame, [30, 55], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const dividerProgress = interpolate(frame, [40, 55], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Phase 3: 55 - 80 frames: Group Colors Transition & Labels Fade In
  const labelsOpacity = interpolate(frame, [55, 80], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const labelsY = interpolate(frame, [55, 80], [15, 0], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dynamic alignment for labels
  const leftLabelX = width / 2 - width * 0.2 - splitProgress * (width * 0.08);
  const rightLabelX = width / 2 + width * 0.2 + splitProgress * (width * 0.08);

  // Phase 4: 80 - 105 frames: Stopwatch and "6 MONTHS" appearance
  const stopwatchSpring = spring({
    frame: frame - 80,
    fps,
    config: { damping: 12, mass: 0.9 },
  });

  const stopwatchOpacity = interpolate(frame, [80, 95], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const stopwatchScale = interpolate(stopwatchSpring, [0, 1], [0.5, 1]);

  const text6MonthsOpacity = interpolate(frame, [90, 115], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const text6MonthsX = interpolate(frame, [90, 115], [-15, 0], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Phase 5: 135 - 180 frames (1.5 seconds @ 30fps): Everything except the "6 MONTHS" stopwatch fades out smoothly
  const scene1FadeOut = interpolate(frame, [135, 180], [1, 0], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // ----------------------------------------------------
  // SCENE 2 TIMINGS (180 - 280 frames)
  // ----------------------------------------------------
  
  // Bars rise from frame 180 to 215
  const barHeightProgress = interpolate(frame, [180, 215], [0, 1], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const barLabelsOpacity = interpolate(frame, [195, 220], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const equalsOpacity = interpolate(frame, [205, 230], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const captionOpacity = interpolate(frame, [215, 240], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Scene 2 elements fade out smoothly at 275 - 295
  const scene2FadeOut = interpolate(frame, [275, 295], [1, 0], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // ----------------------------------------------------
  // SCENE 3 TIMINGS (290 - 420 frames)
  // ----------------------------------------------------
  const scene3FadeIn = interpolate(frame, [290, 315], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const scene3Spring = spring({
    frame: frame - 290,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  const circleScale = interpolate(scene3Spring, [0, 1], [0.6, 1]);

  // ----------------------------------------------------
  // GRID LAYOUT CALCULATIONS
  // ----------------------------------------------------
  const cols = 10;
  const rows = 10;
  const cellWidth = (width * 0.8) / cols;
  const cellHeight = (width * 0.08);
  const iconSize = cellWidth * 0.6;

  const gridWidth = cols * cellWidth;
  const gridHeight = rows * cellHeight;
  const startX = (width - gridWidth) / 2;
  const startY = (height - gridHeight) / 2 + height * 0.06;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, transition: "none" }}>
      
      {/* ----------------------------------------------------
          TOP COMPOSITION: STOPWATCH & TIME (PERSISTENT)
          ---------------------------------------------------- */}
      <div
        style={{
          position: "absolute",
          top: height * 0.16,
          left: 0,
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 16,
          opacity: stopwatchOpacity,
          transform: `scale(${stopwatchScale})`,
          transition: "none",
        }}
      >
        <StopwatchIcon color={textColor} size={width * 0.09} />
        <span
          style={{
            fontSize: width * 0.075,
            fontWeight: 800,
            color: textColor,
            opacity: text6MonthsOpacity,
            transform: `translateX(${text6MonthsX}px)`,
            letterSpacing: "1px",
            transition: "none",
          }}
        >
          {timeLabel}
        </span>
      </div>

      {/* ----------------------------------------------------
          SCENE 1: HUMAN GRID COMPARISON
          ---------------------------------------------------- */}
      {scene1FadeOut > 0 && (
        <>
          {/* Divider Line */}
          {dividerProgress > 0 && (
            <div
              style={{
                position: "absolute",
                left: width / 2 - 1,
                top: startY - width * 0.02,
                width: 2,
                height: gridHeight + width * 0.04,
                backgroundColor: textColor,
                opacity: dividerProgress * scene1FadeOut,
                transform: `scaleY(${dividerProgress})`,
                transformOrigin: "center",
                transition: "none",
              }}
            />
          )}

          {/* Left Label */}
          <div
            style={{
              position: "absolute",
              left: leftLabelX,
              top: startY - width * 0.09,
              transform: `translate(-50%, ${labelsY}px)`,
              opacity: labelsOpacity * scene1FadeOut,
              textAlign: "center",
              width: cellWidth * 5,
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              textTransform: "uppercase",
              letterSpacing: "0.5px",
              transition: "none",
            }}
          >
            {leftGroupLabel}
          </div>

          {/* Right Label */}
          <div
            style={{
              position: "absolute",
              left: rightLabelX,
              top: startY - width * 0.09,
              transform: `translate(-50%, ${labelsY}px)`,
              opacity: labelsOpacity * scene1FadeOut,
              textAlign: "center",
              width: cellWidth * 5,
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              textTransform: "uppercase",
              letterSpacing: "0.5px",
              transition: "none",
            }}
          >
            {rightGroupLabel}
          </div>

          {/* Grid of Figures */}
          {Array.from({ length: 100 }).map((_, index) => {
            const row = Math.floor(index / cols);
            const col = index % cols;
            const isLeftGroup = col < 5;

            const baseX = startX + col * cellWidth + cellWidth / 2;
            const baseY = startY + row * cellHeight + cellHeight / 2;

            const currentShift = isLeftGroup
              ? -splitProgress * (width * 0.08)
              : splitProgress * (width * 0.08);

            const finalX = baseX + currentShift;

            const staggerDelay = random(`stagger-${index}`) * 25;
            const figureOpacity = interpolate(
              frame,
              [staggerDelay, staggerDelay + 15],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const figureColor = interpolateColors(
              frame,
              [55, 80],
              [textColor, isLeftGroup ? leftGroupColor : rightGroupColor]
            );

            return (
              <div
                key={index}
                style={{
                  position: "absolute",
                  left: finalX - iconSize / 2,
                  top: baseY - iconSize / 2,
                  width: iconSize,
                  height: iconSize,
                  opacity: figureOpacity * scene1FadeOut,
                  transition: "none",
                }}
              >
                <StickFigureIcon color={figureColor} size={iconSize} />
              </div>
            );
          })}
        </>
      )}

      {/* ----------------------------------------------------
          SCENE 2: EQUIVALENCE BARS & CAPTION
          ---------------------------------------------------- */}
      {frame >= 170 && scene2FadeOut > 0 && (
        <>
          {/* Left Bar */}
          <div
            style={{
              position: "absolute",
              left: width * 0.28 - (width * 0.18) / 2,
              top: height * 0.45 + (width * 0.35) * (1 - barHeightProgress),
              width: width * 0.18,
              height: (width * 0.35) * barHeightProgress,
              backgroundColor: leftGroupColor,
              borderRadius: "12px 12px 0 0",
              opacity: scene2FadeOut,
              transition: "none",
            }}
          />

          {/* Left Label */}
          <div
            style={{
              position: "absolute",
              left: width * 0.28 - (width * 0.35) / 2,
              top: height * 0.45 + (width * 0.35) + 16,
              width: width * 0.35,
              textAlign: "center",
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              opacity: barLabelsOpacity * scene2FadeOut,
              transition: "none",
            }}
          >
            {leftGroupLabel}
          </div>

          {/* Equals Sign */}
          <div
            style={{
              position: "absolute",
              left: width * 0.5 - 25,
              top: height * 0.45 + (width * 0.35) / 2 - 25,
              width: 50,
              height: 50,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: width * 0.1,
              fontWeight: 700,
              color: textColor,
              opacity: equalsOpacity * scene2FadeOut,
              transition: "none",
            }}
          >
            =
          </div>

          {/* Right Bar */}
          <div
            style={{
              position: "absolute",
              left: width * 0.72 - (width * 0.18) / 2,
              top: height * 0.45 + (width * 0.35) * (1 - barHeightProgress),
              width: width * 0.18,
              height: (width * 0.35) * barHeightProgress,
              backgroundColor: rightGroupColor,
              borderRadius: "12px 12px 0 0",
              opacity: scene2FadeOut,
              transition: "none",
            }}
          />

          {/* Right Label */}
          <div
            style={{
              position: "absolute",
              left: width * 0.72 - (width * 0.35) / 2,
              top: height * 0.45 + (width * 0.35) + 16,
              width: width * 0.35,
              textAlign: "center",
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              opacity: barLabelsOpacity * scene2FadeOut,
              transition: "none",
            }}
          >
            {rightGroupLabel}
          </div>

          {/* Caption */}
          <div
            style={{
              position: "absolute",
              left: width * 0.05,
              top: height * 0.45 + (width * 0.35) + width * 0.18,
              width: width * 0.9,
              textAlign: "center",
              fontSize: width * 0.045,
              fontWeight: 600,
              color: textColor,
              opacity: captionOpacity * scene2FadeOut,
              transition: "none",
            }}
          >
            No significant difference (P&gt;0.05)
          </div>
        </>
      )}

      {/* ----------------------------------------------------
          SCENE 3: SCALP IRRITATION CIRCLES
          ---------------------------------------------------- */}
      {frame >= 285 && (
        <>
          {/* Left Circle Icon */}
          <div
            style={{
              position: "absolute",
              left: width * 0.28 - (width * 0.22) / 2,
              top: height * 0.46,
              width: width * 0.22,
              height: width * 0.22,
              borderRadius: "50%",
              backgroundColor: leftGroupColor,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `scale(${circleScale})`,
              opacity: scene3FadeIn,
              transition: "none",
            }}
          >
            <UpArrowIcon color="#FFFFFF" size={(width * 0.22) * 0.5} />
          </div>

          {/* Left Circle Label */}
          <div
            style={{
              position: "absolute",
              left: width * 0.1,
              top: height * 0.46 + (width * 0.22) + 24,
              width: width * 0.36,
              textAlign: "center",
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              opacity: scene3FadeIn,
              lineHeight: 1.3,
              transition: "none",
            }}
          >
            Higher scalp irritation
          </div>

          {/* Right Circle Icon */}
          <div
            style={{
              position: "absolute",
              left: width * 0.72 - (width * 0.22) / 2,
              top: height * 0.46,
              width: width * 0.22,
              height: width * 0.22,
              borderRadius: "50%",
              backgroundColor: rightGroupColor,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `scale(${circleScale})`,
              opacity: scene3FadeIn,
              transition: "none",
            }}
          >
            <DownArrowIcon color="#FFFFFF" size={(width * 0.22) * 0.5} />
          </div>

          {/* Right Circle Label */}
          <div
            style={{
              position: "absolute",
              left: width * 0.54,
              top: height * 0.46 + (width * 0.22) + 24,
              width: width * 0.36,
              textAlign: "center",
              fontSize: width * 0.042,
              fontWeight: 700,
              color: textColor,
              opacity: scene3FadeIn,
              lineHeight: 1.3,
              transition: "none",
            }}
          >
            Lower scalp irritation
          </div>
        </>
      )}

    </AbsoluteFill>
  );
};

export default HumanComparison;